#include <bits/stdc++.h>
using namespace std;

bool find_pair(vector<int>& a, int n, int k) {
	unordered_set<int> us;
	for (int i = 0; i < n; ++i) {
		if (us.count(k - a[i])) {
			return true;
		}
		us.insert(a[i]);
	}
	return false;
}

int main() {
	int n, k;
	cin >> n >> k;
	vector<int> a(n);
	int multiple = 0, half = 0;
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
		a[i] %= k;
		if (a[i] % k == 0) {
			++multiple;
		} else if (k % 2 == 0 && a[i] % k == k / 2) {
			++half;
		}
	}
	if (max(multiple, half) >= 2) {
		cout << max(multiple, half) << endl;
	} else if (find_pair(a, n, k)) {
		cout << 2 << endl;
	} else {
		cout << -1 << endl;
	}
	return 0;
}
```

